fn assert_no_call_site_owned_at_span(
    graph: &impl GraphAccess,
    owner: &CallOwnerContext,
    span: (usize, usize),
) {
    let matches = graph
        .call_sites()
        .iter()
        .filter(|call| call.owner() == owner.id && call.span() == span)
        .collect::<Vec<_>>();
    assert!(
        matches.is_empty(),
        "expected no call site owned by {} at {span:?}, found {matches:#?}",
        owner.label
    );
}

fn assert_no_path_call_owned_by_path(
    graph: &impl GraphAccess,
    owner: &CallOwnerContext,
    path: &[&str],
) {
    let expected_path = path.iter().copied().map(String::from).collect::<Vec<_>>();
    let matches = graph
        .call_sites()
        .iter()
        .filter(|call| call.owner() == owner.id)
        .filter_map(|call| match call {
            CallNode::PathCall(path_call) if path_call.path == expected_path => Some(call),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert!(
        matches.is_empty(),
        "expected no path call owned by {} with path {path:?}, found {matches:#?}",
        owner.label
    );
}

fn assert_closure_body_path_call_owned_at_span(
    graph: &impl GraphAccess,
    parent: &CallOwnerContext,
    span: (usize, usize),
    path: &[&str],
) {
    assert_executable_body_path_call_owned_at_span(
        graph,
        parent,
        ExecutableBodyKind::Closure,
        span,
        path,
    );
}

fn assert_executable_body_path_call_owned_at_span(
    graph: &impl GraphAccess,
    parent: &CallOwnerContext,
    kind: ExecutableBodyKind,
    span: (usize, usize),
    path: &[&str],
) {
    let bodies = graph
        .executable_bodies()
        .iter()
        .filter(|body| {
            body.parent == parent.id
                && body.kind == kind
                && body.span.0 <= span.0
                && span.1 <= body.span.1
        })
        .collect::<Vec<_>>();
    assert_eq!(
        bodies.len(),
        1,
        "expected one {kind:?} body owned by {} containing {span:?}, found {bodies:#?}",
        parent.label
    );

    let owner = CallBodyOwnerId::Executable(bodies[0].id);
    let calls = graph
        .call_sites()
        .iter()
        .filter(|call| call.owner() == owner && call.span() == span)
        .collect::<Vec<_>>();
    assert_eq!(
        calls.len(),
        1,
        "expected one {kind:?}-owned call site at {span:?}, found {calls:#?}"
    );

    let CallNode::PathCall(call) = calls[0] else {
        panic!(
            "expected {kind:?}-owned path call at {span:?}, found {:#?}",
            calls[0]
        );
    };
    let expected_path = path.iter().copied().map(String::from).collect::<Vec<_>>();
    assert_eq!(call.path, expected_path);

    let relations = graph
        .call_site_relations()
        .iter()
        .filter(|relation| {
            matches!(
                relation,
                CallSiteRelation::BodyContainsCall { source, target }
                    if *source == owner && *target == calls[0].id()
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        relations.len(),
        1,
        "expected one {kind:?} BodyContainsCall relation for {span:?}, found {relations:#?}"
    );
}

fn assert_executable_body_path_call_owned_by_label(
    graph: &impl GraphAccess,
    parent: &CallOwnerContext,
    kind: ExecutableBodyKind,
    label: Option<&str>,
    path: &[&str],
) {
    let bodies = graph
        .executable_bodies()
        .iter()
        .filter(|body| {
            body.parent == parent.id && body.kind == kind && body.label.as_deref() == label
        })
        .collect::<Vec<_>>();
    assert_eq!(
        bodies.len(),
        1,
        "expected one {kind:?} body owned by {} with label {label:?}, found {bodies:#?}",
        parent.label
    );

    let owner = CallBodyOwnerId::Executable(bodies[0].id);
    let expected_path = path.iter().copied().map(String::from).collect::<Vec<_>>();
    let calls = graph
        .call_sites()
        .iter()
        .filter(|call| call.owner() == owner)
        .filter_map(|call| match call {
            CallNode::PathCall(path_call) if path_call.path == expected_path => Some(call),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        calls.len(),
        1,
        "expected one {kind:?}-owned path call {path:?}, found {calls:#?}"
    );

    let relations = graph
        .call_site_relations()
        .iter()
        .filter(|relation| {
            matches!(
                relation,
                CallSiteRelation::BodyContainsCall { source, target }
                    if *source == owner && *target == calls[0].id()
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        relations.len(),
        1,
        "expected one {kind:?} BodyContainsCall relation for path {path:?}, found {relations:#?}"
    );
}

fn assert_executable_body_label_at_span(
    graph: &impl GraphAccess,
    parent: &CallOwnerContext,
    kind: ExecutableBodyKind,
    span: (usize, usize),
    label: Option<&str>,
) {
    let bodies = graph
        .executable_bodies()
        .iter()
        .filter(|body| {
            body.parent == parent.id
                && body.kind == kind
                && body.span.0 <= span.0
                && span.1 <= body.span.1
        })
        .collect::<Vec<_>>();
    assert_eq!(
        bodies.len(),
        1,
        "expected one {kind:?} body owned by {} containing {span:?}, found {bodies:#?}",
        parent.label
    );
    assert_eq!(
        bodies[0].label.as_deref(),
        label,
        "unexpected {kind:?} executable body label for {span:?}"
    );
}

fn closure_body_inside_span(
    graph: &impl GraphAccess,
    owner: &CallOwnerContext,
    span: (usize, usize),
) -> ExecutableBodyId {
    let bodies = graph
        .executable_bodies()
        .iter()
        .filter(|body| {
            body.parent == owner.id
                && body.kind == ExecutableBodyKind::Closure
                && span.0 <= body.span.0
                && body.span.1 <= span.1
        })
        .collect::<Vec<_>>();
    assert_eq!(
        bodies.len(),
        1,
        "expected one closure body owned by {} inside {span:?}, found {bodies:#?}",
        owner.label
    );
    bodies[0].id
}

